<?php
require_once __DIR__ . '/../include/session.php';require_once __DIR__ . '/../include/config.php';
if(empty($_SESSION['user'])){header('Location: '.BASE_URL.'/index.php');exit;}if(($_SESSION['user']['role']??'')!=='Admin'){http_response_code(403);exit('Hanya Admin yang dapat menghapus surat.');}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: '.BASE_URL.'/admin/dashboard.php');exit;}$token=$_POST['csrf_token']??'';if(!is_string($token)||empty($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)){http_response_code(419);exit('Formulir kedaluwarsa.');}
$id=max(0,(int)($_POST['id']??0));$stmt=$conn->prepare('SELECT jenis_surat,uploaded_file FROM surat WHERE id=? LIMIT 1');$stmt->bind_param('i',$id);$stmt->execute();$letter=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$letter){$_SESSION['flash']=['type'=>'error','message'=>'Surat tidak ditemukan.'];header('Location: '.BASE_URL.'/admin/dashboard.php');exit;}
$delete=$conn->prepare('DELETE FROM surat WHERE id=?');$delete->bind_param('i',$id);$delete->execute();$delete->close();if(!empty($letter['uploaded_file'])){$path=__DIR__.'/../uploads/surat/'.basename($letter['uploaded_file']);if(is_file($path))unlink($path);}$folder=$letter['jenis_surat']==='Masuk'?'surat_masuk':'surat_keluar';$_SESSION['flash']=['type'=>'success','message'=>'Surat dan riwayatnya berhasil dihapus.'];header('Location: '.BASE_URL.'/admin/'.$folder.'/index.php');exit;
